interface Notification {
    void send(String message);
}

final class EmailNotification implements Notification {
    private final String smtpHost;
    EmailNotification(String smtpHost) { this.smtpHost = smtpHost; }
    @Override public void send(String message) {
        // use smtpHost to deliver; omitted
    }
}

final class SmsNotification implements Notification {
    private final String gateway;
    SmsNotification(String gateway) { this.gateway = gateway; }
    @Override public void send(String message) {
        // use gateway to deliver; omitted
    }
}

abstract class Notifier {
    // Factory Method: subclasses decide which product.
    protected abstract Notification createNotification();

    // Template workflow shared by all creators.
    public final void notifyUser(String message) {
        Notification n = createNotification();
        n.send(message);
    }
}

final class EmailNotifier extends Notifier {
    private final String smtpHost;
    EmailNotifier(String smtpHost) { this.smtpHost = smtpHost; }
    @Override protected Notification createNotification() {
        return new EmailNotification(smtpHost);
    }
}

final class SmsNotifier extends Notifier {
    private final String gateway;
    SmsNotifier(String gateway) { this.gateway = gateway; }
    @Override protected Notification createNotification() {
        return new SmsNotification(gateway);
    }
}

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;

final class NotificationFactory {
    private final Map<String, Supplier<Notification>> registry = new ConcurrentHashMap<>();

    public void register(String key, Supplier<Notification> supplier) {
        registry.put(normalize(key), supplier);
    }

    public Notification create(String key) {
        Supplier<Notification> s = registry.get(normalize(key));
        if (s == null) {
            throw new IllegalArgumentException("unknown notification type: " + key);
        }
        return s.get();
    }

    private static String normalize(String key) {
        return key.trim().toLowerCase();
    }
}
